// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.18;

import {IAsset} from "./IAsset.sol";

// For full documentation refer to src/Allowances.sol";
interface IAllowances {
  ////////////////
  // Allowances //
  ////////////////

  struct AssetAllowance {
    IAsset asset;
    uint positive;
    uint negative;
  }

  struct SubIdAllowance {
    IAsset asset;
    uint subId;
    uint positive;
    uint negative;
  }

  struct PermitAllowance {
    // who to approve
    address delegate;
    // nonce for each signer
    uint nonce;
    // access are granted on account bases. A signer can have multiple accounts and the signature cannot be
    // applied to permit another account
    uint accountId;
    // deadline on the permit signature
    uint deadline;
    // array of "asset allowance" to set
    IAllowances.AssetAllowance[] assetAllowances;
    // array of "subid allowance" to set
    SubIdAllowance[] subIdAllowances;
  }

  ///////////
  // Views //
  ///////////

  function positiveSubIdAllowance(uint accountId, address owner, IAsset asset, uint subId, address spender)
    external
    view
    returns (uint);

  function negativeSubIdAllowance(uint accountId, address owner, IAsset asset, uint subId, address spender)
    external
    view
    returns (uint);

  function positiveAssetAllowance(uint accountId, address owner, IAsset asset, address spender)
    external
    view
    returns (uint);

  function negativeAssetAllowance(uint accountId, address owner, IAsset asset, address spender)
    external
    view
    returns (uint);

  ////////////
  // Errors //
  ////////////

  error NotEnoughSubIdOrAssetAllowances(
    address caller, uint accountId, int amount, uint subIdAllowance, uint assetAllowance
  );
}

src/interfaces/IAsset.sol.content:
// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.18;

import {IManager} from "./IManager.sol";
import {ISubAccounts} from "./ISubAccounts.sol";

interface IAsset {
  /**
   * @notice triggered when an adjustment is triggered on the asset balance
   * @param adjustment details about adjustment, containing account, subId, amount
   * @param tradeId unique number attached to a batched transfers.
   *                It is possible that this hook will receive multiple calls with different tradeIds within 1 transaction.
   * @param preBalance balance before adjustment
   * @param manager the manager contract that will verify the end state. Should verify if this is a trusted manager
   * @param caller the msg.sender that initiate the transfer. might not be the owner
   * @return finalBalance the final balance to be recorded in the account
   * @return needAllowance if this adjustment should require allowance from non-ERC721 approved initiator
   */
  function handleAdjustment(
    ISubAccounts.AssetAdjustment memory adjustment,
    uint tradeId,
    int preBalance,
    IManager manager,
    address caller
  ) external returns (int finalBalance, bool needAllowance);
}

